def antwoord(vraag, bestaand=""):
    if bestaand:
        return bestaand
    if vraag in ALG: return ALG[vraag]
    if vraag in EXTRA: return EXTRA[vraag]
    if vraag.startswith("Wat kost"):
        onderwerp = vraag[len("Wat kost "):].rstrip("?")
        return kost(onderwerp.replace("een ", "een ", 1))
    raise KeyError(vraag)
